from collections import defaultdict
W=defaultdict(lambda:defaultdict(int))
for l in WEIGHTS.splitlines():
 if l.startswith('order'):
  order,apex,flip=tuple(int(q.split('=')[1])for q in l.split())
 else:
  v,f,b,k=map(int,l.split());W[order,flip][v,f,b]+=k
def guide(s):
  v=f=b=0
  for i,c in enumerate(s):
   if c:
    v|=1<<i
    if c>=3:f|=1<<i
    if c%2:b|=1<<i
  return v,f,b
R={}
for label,weights in W.items():
 for s in product(range(5),repeat=3):
  v,forbid_f,forbid_b=guide(s)
  R[label,s]=sum(k for (vv,f,b),k in weights.items() if v==vv and not f&forbid_f and not b&forbid_b)
def counts(word,order=0):
  A={(0,0,0):1}
  for b in word:
   B=defaultdict(int)
   for s,k in A.items():
    for i,c in enumerate(s):
     # 1,2,3,4 model (first,last)=(0,0),(0,1),(1,0),(1,1)
     w=(1+3*b)if not c else ((c-1)&2)+1+b
     B[s[:i]+(w,)+s[i+1:]]+=k
   A=B
  return tuple(sum(R[(order,flip),s]*k for s,k in A.items()) for flip in (0,1))
from itertools import product
from functools import cache

def host(U,V,um,vm,word,flip):
    m=len(word);n=len(U)+m+len(V); A=[0]*(n+2);x,a=n,n+1
    start=len(U)+m
    for i,r in enumerate(U):A[i]=r|(((1<<(m+len(V)))-1)<<len(U))
    for j in range(m):A[len(U)+j]=(1<<n)-(1<<(len(U)+j+1))
    for i,r in enumerate(V):A[i+start]=r<<start
    mask=(1<<n)-1
    w=sum(b<<j for j,b in enumerate(word))
    for p,pi in ((x,0),(a,1)):
        inn=um[pi]|(vm[pi]<<start)|(w<<len(U))
        A[p]=mask^inn
        for i in range(n):
            if inn>>i&1:A[i]|=1<<p
    if flip:A[a]|=1<<x
    else:A[x]|=1<<a
    return A

def H(A):
    @cache
    def f(S,i):
        if not S:return 1
        r=S&A[i];h=0
        while r:
            z=r&-r;r-=z;h+=f(S^z,z.bit_length()-1)
        return h
    return sum(f(((1<<len(A))-1)^(1<<i),i)for i in range(len(A)))

A=(2,4,1); B=(2,12,17,37,75,87,143,63)
p=(1,4);q=(37,67)
def verify_literal():
    for i,(U,V,um,vm) in enumerate(((A,B,p,q),(B,A,q,p))):
        for n in range(4):
            for word in product((0,1),repeat=n):
                true=tuple(H(host(U,V,um,vm,word,j))for j in (0,1))
                assert true==counts(word,i),(word,i,true,counts(word,i))
    print("60 literal port-switch counts match the compressed transfer")

if __name__=='__main__':
    for n in range(11):
        read=[]
        for o in (0,1):
            centers=set()
            for w in product((0,1),repeat=n):
                a,b=counts(w,o)
                assert a&1 and b-a==2 and a>=3**n
                centers.add(a+1)
            read.append(centers)
        if n>=3: assert all(len(s)==1<<n for s in read) and not (read[0]&read[1])
    verify_literal()
    # The top mixed difference of four disjoint adjacent pair switches.
    for o in (0,1):
        mixed=0
        for v in product((0,1),repeat=4):
            w=tuple(y for bit in v for y in ((1,0) if bit else (0,1)))
            mixed+=(-1)**sum(v)*(counts(w,o)[0]+1)
        assert mixed==11592
    print("The charged eight-contact cube has fourth mixed difference 11592")
